const id = $("Webhook").item.json.body.orderId?.trim().toUpperCase();

if (!id) {
  return [{
    json: {
      message: "Please enter an order number."
    }
  }];
}

if (!orders[id]) {
  return [{
    json: {
      message: "Order not found. Please check the order number."
    }
  }];
}

const order = orders[id];

const deliveryLabel =
  order.status === "Delivered"
    ? `Delivered On: ${order.expectedDelivery}`
    : `Expected Delivery: ${order.expectedDelivery}`;

return [{
  json: {
    message:
      `Order ${id}\n` +
      `Product: ${order.product}\n` +
      `Status: ${order.status}\n` +
      `Tracking: ${order.trackingNumber}\n` +
      `${deliveryLabel}\n` +
      `Fulfilment Centre: ${order.deliveryCentre}`
  }
}];

const stock = [
  {
    product: "Blue T-Shirt",
