    status: "Out of Stock",
    quantity: 0,
    restockDate: "21 Aug 2026",
    availableAt: null
  }
];

const body = $("Webhook").item.json.body;

const product = body.product?.trim().toLowerCase();
const size = body.size?.trim().toLowerCase();

if (!product || !size) {
  return [{
    json: {
      message: "Please enter both product and size."
    }
  }];
}

const match = stock.find(
  item =>
    item.product.toLowerCase() === product &&
    item.size.toLowerCase() === size
);

if (!match) {
  return [{
    json: {
      message: "Product/size combination not found."
    }
  }];
}

let message =
  `${match.product}, size ${match.size}\n` +
  `Status: ${match.status}\n` +
  `Quantity: ${match.quantity}`;

if (match.status === "In Stock") {
  message += `\nAvailable at: ${match.availableAt}`;
} else {
  message += `\nExpected Restock: ${match.restockDate}`;
}

return [{
  json: {
    message
  }
}];
